def solve_cvrp(instance):
    # Deterministic constructive CVRP solver with simple repair.
    # Output: list of routes; each route is a list of customer IDs (no depot).

    # Helper: distance (no imports)
    def dist(a, b):
        dx = a['x'] - b['x']
        dy = a['y'] - b['y']
        return (dx*dx + dy*dy) ** 0.5

    # Extract data from instance
    depot = {'id': 0, 'x': 0.0, 'y': 0.0}
    if isinstance(instance, dict):
        if 'depot' in instance:
            depot = instance['depot']
        if 'customers' in instance:
            customers = instance['customers']
        elif 'nodes' in instance:
            customers = instance['nodes']
        else:
            customers = []
    else:
        customers = []

    vehicle_capacity = instance.get('vehicle_capacity', 1000) if isinstance(instance, dict) else 1000

    # Normalize customers: ensure required fields
    reqs = []
    for c in customers:
        cid = c.get('id')
        if cid is None:
            continue
        d = c.get('demand', 0)
        x = c.get('x', 0.0)
        y = c.get('y', 0.0)
        reqs.append({'id': cid, 'demand': d, 'x': x, 'y': y})

    # If no customers, return empty routes
    if not reqs:
        return []

    # Deterministic order: by angle around depot, then by id
    import math
    def key_by_angle(item):
        dx = item['x'] - depot.get('x', 0.0)
        dy = item['y'] - depot.get('y', 0.0)
        angle = math.atan2(dy, dx)
        return (angle, item['id'])

    try:
        reqs.sort(key=key_by_angle)
    except Exception:
        reqs.sort(key=lambda t: t['id'])

    # Construct routes greedily
    routes = []
    current_route = []
    current_load = 0

    for c in reqs:
        d = c['demand']
        if d > vehicle_capacity:
            # Single-customer route
            if current_route:
                routes.append(current_route)
                current_route = []
                current_load = 0
            routes.append([c['id']])
            continue

        if current_load + d <= vehicle_capacity:
            current_route.append(c['id'])
            current_load += d
        else:
            if current_route:
                routes.append(current_route)
            current_route = [c['id']]
            current_load = d

    if current_route:
        routes.append(current_route)

    # Repair: ensure all customers present
    visited = set(cid for r in routes for cid in r)
    all_ids = {c['id'] for c in reqs}
    missing = sorted(all_ids - visited)
    for mid in missing:
        routes.append([mid])

    # Local-ish improvement: try simple merge if capacity allows
    i = 0
    while i < len(routes) - 1:
        r1 = routes[i]
        r2 = routes[i+1]

        # compute route demands
        def route_demand(r):
            s = 0
            for cid in r:
                for c in reqs:
                    if c['id'] == cid:
                        s += c['demand']
                        break
            return s

        d1 = route_demand(r1)
        d2 = route_demand(r2)

        if d1 + d2 <= vehicle_capacity:
            if r1:
                cid_from_r1 = r1[-1]
                # Move last of r1 to start of r2 if reasonable (deterministic)
                r1 = r1[:-1]
                r2 = [cid_from_r1] + r2
                routes[i] = r1
                routes[i+1] = r2
                i = max(i - 1, 0)
                continue

        i += 1

    # Remove empty routes if any
    routes = [r for r in routes if r]

    return routes
